class TFMLogicInputOutputContainer
{
    Map	connection;
    Map	connectionBlocks;

}

Method.Source:
protected void new()
{
    connection          = new Map(Types::Integer, Types::String);
    connectionBlocks    = new Map(Types::Integer, Types::Class);
}

public static TFMLogicInputOutputContainer Construct()
{
    return new TFMLogicInputOutputContainer();
}

public str getConnectionName(int _id)
{
    return connection.exists(_id) ? connection.lookup(_id) : '';
}

public int getIdFromConnectionName(str _connectionName)
{
    MapEnumerator mEnum;
    mEnum = connection.getEnumerator();
    while (mEnum.moveNext())
    {
        if (mEnum.currentValue() == _connectionName)
        {
            return mEnum.currentKey();
        }
    }
    return 1;
}

public TFMLogicBlock getBlockAtConnection(int _id)
{
    TFMLogicBlock logicBlock;

    return logicBlock;
}

public TFMLogicBlock getBlockAtConnectionName(str _name)
{
    TFMLogicBlock logicBlock;

    return logicBlock;
}
